#include <iostream>

static int n;
static int ans = 0;
static bool col[15];
static bool diag1[29];
static bool diag2[29];

void solve(int r) {
    if (r == n) {
        ++ans;
        return;
    }
    for (int c = 0; c < n; ++c) {
        if (col[c] || diag1[r + c] || diag2[r - c + n - 1]) continue;
        col[c] = true;
        diag1[r + c] = true;
        diag2[r - c + n - 1] = true;

        solve(r + 1);

        col[c] = false;
        diag1[r + c] = false;
        diag2[r - c + n - 1] = false;
    }
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    if (!(std::cin >> n)) return 0;

    solve(0);
    std::cout << ans << '\n';

    return 0;
}
